class DadosEntrada:
    orbe: pd.DataFrame
    taxas: pd.DataFrame
    ponte: pd.DataFrame
    plano_contas: pd.DataFrame
    aurora: pd.DataFrame
    meridiano: pd.DataFrame


def carregar(input_dir: Path) -> DadosEntrada:
    return DadosEntrada(
        orbe=carregar_orbe(input_dir),
